package com.desktodo.app;
import android.app.*;import android.os.*;import org.json.*;import java.time.*;
/** Isolated data contracts, privacy boundaries and undo; no live network or task writes. */
public final class ExtensionChecks extends Instrumentation {
 int count;void check(boolean b,String message){count++;if(!b)throw new AssertionError(message);}interface Work{void run()throws Exception;}void rejects(Work w,String m)throws Exception{boolean failed=false;try{w.run();}catch(Exception e){failed=true;}check(failed,m);}
 @Override public void onCreate(Bundle b){start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
 JSONObject cfg=DeskModel.defaults().put("origin","secret").put("key","secret").put("tasks",new JSONArray().put("private"));JSONObject t=DeskExtras.template(cfg,"fixture");check(!t.getJSONObject("settings").has("key")&&!t.getJSONObject("settings").has("tasks")&&!t.getJSONObject("settings").has("origin"),"templates strip private fields");JSONObject restored=DeskExtras.importTemplate(cfg,t);check(restored.optString("layout").equals("overview")&&restored.optString("key").equals("secret"),"import changes visual fields only");rejects(()->DeskExtras.importTemplate(cfg,new JSONObject().put("schema","bad").put("settings",new JSONObject())),"invalid template rejected");rejects(()->DeskExtras.template(DeskModel.copy(cfg).put("ratio",99),"invalid"),"invalid ratio rejected");
 JSONArray habits=DeskExtras.addHabit(new JSONArray(),"阅读");String id=habits.getJSONObject(0).getString("id");LocalDate today=LocalDate.of(2026,10,18);JSONArray checked=DeskExtras.toggle(habits,id,today);check(DeskExtras.checked(checked.getJSONObject(0),today),"mark today");check(!DeskExtras.checked(checked.getJSONObject(0),today.plusDays(1)),"next day resets");check(!DeskExtras.checked(DeskExtras.toggle(checked,id,today).getJSONObject(0),today),"undo mark");JSONArray three=DeskExtras.addHabit(DeskExtras.addHabit(habits,"喝水"),"伸展");rejects(()->DeskExtras.addHabit(three,"第四个"),"three-habit limit");
 JSONObject sensitive=DeskModel.defaults().put("nextEvent",new JSONObject().put("title","PRIVATE CALENDAR")).put("habits",habits).put("favorites",new JSONArray().put(t));check(!DeskExtras.agentConfig(sensitive).has("nextEvent")&&!DeskExtras.agentConfig(sensitive).has("habits")&&!DeskExtras.agentConfig(sensitive).has("favorites"),"new personal data excluded from model context");
 JSONObject local=DeskModel.defaults().put("favorites",new JSONArray().put(t)).put("calendarIDs",new JSONArray().put("private")).put("habits",checked);JSONObject device=DeskExtras.deviceConfig(local);check(!device.has("favorites")&&!device.has("calendarIDs"),"private local config excluded from display metadata");check(device.optJSONArray("habits").getJSONObject(0).getJSONArray("days").length()<=1,"display gets compact current-day marks");
 long stamp=Instant.parse("2026-10-18T04:00:00Z").toEpochMilli();JSONArray ledger=new JSONArray().put(new JSONObject().put("id","task-id").put("completedAt","2026-10-18T03:00:00Z"));JSONObject captured=SharedData.capture(new JSONObject(),ledger,new JSONArray(),DeskModel.defaults().put("habits",checked),stamp);check(captured.getJSONObject("completions").length()==1,"completion keyed by task ID");JSONObject repeat=SharedData.capture(captured,ledger,new JSONArray(),DeskModel.defaults().put("habits",checked),stamp+1000);check(repeat.getJSONObject("completions").getJSONObject("task-id").getLong("stamp")==stamp,"repeat doesn't invent new timestamp");JSONObject undone=SharedData.capture(captured,new JSONArray(),new JSONArray().put(new JSONObject().put("id","task-id")),DeskModel.defaults().put("habits",habits),stamp+1000);check(undone.getJSONObject("completions").getJSONObject("task-id").getBoolean("deleted"),"undo tombstone");check(!undone.getJSONObject("habits").getJSONObject(id).getJSONObject("days").getJSONObject(today.toString()).getBoolean("checked"),"shared unchecked tombstone");check(SharedData.capture(undone,ledger,new JSONArray(),DeskModel.defaults().put("habits",habits),stamp+2000).getJSONObject("completions").getJSONObject("task-id").getBoolean("deleted"),"old ledger cannot resurrect remote undo");check(SharedData.ledger(undone).length()==0,"undo not counted");check(SharedData.apply(DeskModel.defaults(),captured).getJSONArray("habits").length()==1,"shared habit applies");
 JSONObject plugin=new JSONObject().put("schema","mojian-card-v1").put("name","fixture").put("kind","countdown").put("title","交付").put("date","2026-10-20");check(CommunityPanel.pluginText(plugin,today).contains("2 天"),"deterministic plugin countdown");rejects(()->CommunityPanel.validatePlugin(DeskModel.copy(plugin).put("kind","script")),"scripts rejected");check(CommunityPanel.address("http://192.168.1.2:8788").startsWith("http"),"local hub allowed");rejects(()->CommunityPanel.address("http://192.168.attacker.example"),"private-prefix DNS not trusted");rejects(()->CommunityPanel.address("http://example.com"),"remote plain HTTP rejected");rejects(()->CommunityPanel.address("https://key@example.com"),"embedded credentials rejected");
 result.putString("stream","PASS: "+count+" extension contracts: template privacy, habit undo/day rollover, shared dedupe/tombstones, compact display metadata, plugin validation and remote transport policy\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL: "+e+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
